operation.add:
    $data['infopix'] = false;
    $data['infobol'] = false; 
    if (isset($this->session->data['order_id'])) {
		$ord = $this->session->data['order_id'];

		$this->load->model('checkout/order');
		$order_info = $this->model_checkout_order->getOrder($ord);

		if ($order_info && $order_info['payment_code'] == 'asaas_pix') {
          $payid = $this->getLink($ord);
          $res_api = $this->getPay($payid);
          $data['qrcode'] = 'data:image/png;base64, ' . $res_api['pix']['encodedImage'];
          $data['copia'] = $res_api['pix']['payload'];
		      $data['exp'] = $res_api['pix']['expirationDate'];
          $data['bt'] = $this->url->link('account/order/info', 'order_id=' . $ord, true);
          $data['infopix'] = true;
		}

    if ($order_info && $order_info['payment_code'] == 'asaas_boleto') {
          $payid = $this->getLink2($ord);
          $res_api = $this->getPay($payid);
          $data['barcode'] = $res_api['bankSlip']['barCode'];
          $data['linkboleto'] = $res_api['bankSlip']['bankSlipUrl'];
          $data['bt'] = $this->url->link('account/order/info', 'order_id=' . $ord, true);
          $data['infobol'] = true;
		}

    }

        public function getLink($order_id) {
            $query = $this->db->query("SELECT * FROM " . DB_PREFIX . "asaas_callback WHERE order_id = '" . (int)$order_id . "'");
	          if ($query->num_rows) {
              return $query->row['pay_id'];
            } else {
              return false;
            }
        }

        public function getLink2($order_id) {
            $query = $this->db->query("SELECT * FROM " . DB_PREFIX . "asaas_callback WHERE order_id = '" . (int)$order_id . "'");
	          if ($query->num_rows) {
              return $query->row['pay_id'];
            } else {
              return false;
            }
        }

        public function getPay($id) {
          require_once(DIR_SYSTEM . 'library/asaas/asaas_api.php');
          $asaas = new AsaasApi($this->config->get('asaas_pix_api_key'));

          $resposta = $asaas->getPaymentInfo($id);
          return  $resposta;
        }

    if($this->version()) {
		    $data['update_asaas'] = 'Nova versão do módulo <b>Asaas</b> disponível para <a href="https://www.opencart.com/index.php?route=marketplace/extension/info&extension_id=48210" target="_blank">Download</a>!';
		} else {
		   $data['update_asaas'] = '';
		}

    public function version() {
	    $version = '1.0.6.0';
	    $url = base64_decode('aHR0cHM6Ly9vcGVuY2FydG1hc3Rlci5jb20uYnIvbW9kdWxlL3ZlcnNpb24v');
        $soap_do = curl_init();
        curl_setopt($soap_do, CURLOPT_URL, $url);
        curl_setopt($soap_do, CURLOPT_CONNECTTIMEOUT, 10);
        curl_setopt($soap_do, CURLOPT_TIMEOUT,        10);
        curl_setopt($soap_do, CURLOPT_CUSTOMREQUEST, "GET");
        curl_setopt($soap_do, CURLOPT_RETURNTRANSFER, true );
        curl_setopt($soap_do, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($soap_do, CURLOPT_SSL_VERIFYHOST, false);

        $response = curl_exec($soap_do); 
        curl_close($soap_do);
        $resposta = json_decode($response, true);
        if ($resposta['asaas'] > $version) {
            return true;
        } else {
            return  false;
        }
	  }
